import json,re,statistics,time,urllib.request
import serial
p='/dev/cu.usbserial-1130'
h=serial.Serial(p,115200,timeout=0.1,write_timeout=1); h.dtr=False; h.rts=False
start=time.monotonic(); end=start+135; raw=bytearray(); sent=set()
schedule=[(8,b'status\n','status8'),(32,b'sensors\n','sensors32'),(38,b'status\n','status38'),(68,b'sdlog status\n','sdlog68'),(74,b'status\n','status74'),(118,b'status\n','status118')]
while time.monotonic()<end:
    elapsed=time.monotonic()-start
    for at,cmd,name in schedule:
        if elapsed>=at and name not in sent:
            h.write(cmd); h.flush(); sent.add(name)
    n=h.in_waiting
    if n: raw.extend(h.read(n))
    time.sleep(0.05)
time.sleep(2); n=h.in_waiting
if n: raw.extend(h.read(n))
h.close(); text=raw.decode(errors='replace')
print('STAGE28E_C_RUNTIME_SERIAL_CHARS',len(text)); print(text[-50000:])
status=[x for x in text.splitlines() if x.startswith('status ')]
if len(status)<3: raise SystemExit(f'need >=3 complete status samples, got {len(status)}')
def kv(line):
    return dict(re.findall(r'([A-Za-z0-9_]+)=([^ ]+)',line))
rows=[kv(x) for x in status]
for r in rows:
    if r.get('firmware_sha')!='e0fb5da17879569f791898ba793e1c02b195fab8': raise SystemExit('unexpected firmware sha')
    if r.get('outputs')!='fake-locked' or r.get('rf_ready')!='0': raise SystemExit('unsafe/non-fake output state')
for bad in ['heap_integrity_failed','arbiter_counter_regression','Guru Meditation Error','CORRUPT HEAP','Stack canary watchpoint triggered']:
    if bad in text: raise SystemExit('unexpected fault marker '+bad)
if 'stage28e_coredump present=1 valid=1' in text: raise SystemExit('unexpected valid coredump')
